import{_ as t,o as r,c as o,a2 as i}from"./chunks/framework.CAKCj7G0.js";const g=JSON.parse('{"title":"CopyOnWriteArrayList","description":"","frontmatter":{},"headers":[],"relativePath":"Java/Java/集合/Collection/List/CopyOnWriteArrayList.md","filePath":"Java/Java/集合/Collection/List/CopyOnWriteArrayList.md","lastUpdated":1762838572000}'),e={name:"Java/Java/集合/Collection/List/CopyOnWriteArrayList.md"};function l(n,a,s,p,h,d){return r(),o("div",null,[...a[0]||(a[0]=[i(`<h1 id="copyonwritearraylist" tabindex="-1">CopyOnWriteArrayList <a class="header-anchor" href="#copyonwritearraylist" aria-label="Permalink to &quot;CopyOnWriteArrayList&quot;">​</a></h1><h1 id="一、核心定义" tabindex="-1">一、核心定义 <a class="header-anchor" href="#一、核心定义" aria-label="Permalink to &quot;一、核心定义&quot;">​</a></h1><p>CopyOnWriteArrayList 是 Java 并发包（<code>java.util.concurrent</code>）提供的<strong>线程安全 ArrayList 实现</strong>，核心采用“<strong>写时复制（Copy-On-Write）</strong>”机制，专为“读多写少”场景设计，平衡读操作高效性与写操作安全性。</p><p>与普通 ArrayList 核心差异：读操作直接访问原容器（无锁）；写操作（增删改）不修改原容器，而是复制副本修改后替换原引用（加锁保证安全）。</p><h1 id="二、核心原理-写时复制" tabindex="-1">二、核心原理：写时复制 <a class="header-anchor" href="#二、核心原理-写时复制" aria-label="Permalink to &quot;二、核心原理：写时复制&quot;">​</a></h1><h2 id="_2-1-核心逻辑" tabindex="-1">2.1 核心逻辑 <a class="header-anchor" href="#_2-1-核心逻辑" aria-label="Permalink to &quot;2.1 核心逻辑&quot;">​</a></h2><p>底层维护<strong>volatile 修饰的不可变数组</strong>（保证引用可见性），读操作直接访问该数组；写操作遵循“加锁→复制→修改→替换→解锁”五步流程：</p><ol><li><p><strong>加锁</strong>：通过 ReentrantLock 保证同一时间仅一个线程执行写操作；</p></li><li><p><strong>复制副本</strong>：创建新数组（长度随操作类型调整，如添加则+1），复制原数组元素；</p></li><li><p><strong>执行写操作</strong>：在新数组上完成增删改；</p></li><li><p><strong>替换引用</strong>：将原数组引用指向新数组（volatile 保证其他线程可见）；</p></li><li><p><strong>解锁</strong>：释放锁，允许其他写线程执行。</p></li></ol><h2 id="_2-2-关键成员变量" tabindex="-1">2.2 关键成员变量 <a class="header-anchor" href="#_2-2-关键成员变量" aria-label="Permalink to &quot;2.2 关键成员变量&quot;">​</a></h2><ul><li><p><code>final transient ReentrantLock lock</code>：独占锁，控制并发写，避免副本混乱；</p></li><li><p><code>private transient volatile Object[] array</code>：存储元素的核心数组，volatile 仅保证引用可见性。数组本身&quot;不可变&quot;并非语法限制，而是通过写时复制机制约定——原数组创建后其元素和长度不再修改，写操作必创建新数组并替换该引用，实现逻辑上的不可变。</p></li></ul><h1 id="三、核心方法" tabindex="-1">三、核心方法 <a class="header-anchor" href="#三、核心方法" aria-label="Permalink to &quot;三、核心方法&quot;">​</a></h1><h2 id="_3-1-读操作-无锁高效" tabindex="-1">3.1 读操作：无锁高效 <a class="header-anchor" href="#_3-1-读操作-无锁高效" aria-label="Permalink to &quot;3.1 读操作：无锁高效&quot;">​</a></h2><p>直接访问 array 数组，无锁设计，时间复杂度均为 O(1)：</p><ul><li><p><strong>get(int index)</strong>：获取当前数组→校验索引→返回元素，线程安全（访问稳定原数组）；</p></li><li><p><strong>size()</strong>：直接返回当前数组长度（无需维护单独 size 变量）。</p></li></ul><h2 id="_3-2-写操作-加锁复制" tabindex="-1">3.2 写操作：加锁复制 <a class="header-anchor" href="#_3-2-写操作-加锁复制" aria-label="Permalink to &quot;3.2 写操作：加锁复制&quot;">​</a></h2><p>均需遵循“复制前加锁、引用替换后解锁”的规则，复制数组完成写操作，时间复杂度 O(n)（复制成本）：</p><ul><li><p><strong>add(E e)</strong>：复制原数组（长度+1）→末尾加元素→替换引用，读操作可并行；</p></li><li><p><strong>remove(int index)</strong>：复制原数组（长度-1）<strong>过程中</strong>跳过待删元素→替换引用，读可能访问旧数据（最终一致）；</p></li><li><p><strong>set(int index, E element)</strong>：复制原数组→<strong>复制完成后</strong>修改新数组对应元素→替换引用，即使单元素修改也需全量复制。</p></li></ul><h2 id="_3-3-迭代器-弱一致性" tabindex="-1">3.3 迭代器：弱一致性 <a class="header-anchor" href="#_3-3-迭代器-弱一致性" aria-label="Permalink to &quot;3.3 迭代器：弱一致性&quot;">​</a></h2><p>迭代器，表现为“快照迭代”：</p><ul><li><p>创建时保存当前数组快照，迭代过程仅访问该快照；</p></li><li><p>后续写操作修改的新数组，迭代器无法感知（弱一致性）；</p></li><li><p>不支持迭代中写操作（如 remove/add），否则抛 UnsupportedOperationException。</p></li></ul><h1 id="四、适用边界" tabindex="-1">四、适用边界 <a class="header-anchor" href="#四、适用边界" aria-label="Permalink to &quot;四、适用边界&quot;">​</a></h1><h2 id="_4-1-适用场景" tabindex="-1">4.1 适用场景 <a class="header-anchor" href="#_4-1-适用场景" aria-label="Permalink to &quot;4.1 适用场景&quot;">​</a></h2><ul><li><p><strong>读多写少</strong>：如配置缓存、字典表，读高效+写低频可接受；</p></li><li><p><strong>读响应优先</strong>：允许读弱一致、写延迟，如日志查询；</p></li><li><p><strong>简化线程安全</strong>：替代 Collections.synchronizedList，避免读写锁冲突。</p></li></ul><h2 id="_4-2-不适用场景" tabindex="-1">4.2 不适用场景 <a class="header-anchor" href="#_4-2-不适用场景" aria-label="Permalink to &quot;4.2 不适用场景&quot;">​</a></h2><ul><li><p><strong>写频繁</strong>：大数组复制成本极高，性能骤降；</p></li><li><p><strong>内存敏感</strong>：写时双数组共存，可能内存溢出（如百万级元素）；</p></li><li><p><strong>强一致需求</strong>：如金融交易、库存管理，需实时获取最新数据。</p></li></ul><h1 id="五、优缺点总结" tabindex="-1">五、优缺点总结 <a class="header-anchor" href="#五、优缺点总结" aria-label="Permalink to &quot;五、优缺点总结&quot;">​</a></h1><h2 id="_5-1-优点" tabindex="-1">5.1 优点 <a class="header-anchor" href="#_5-1-优点" aria-label="Permalink to &quot;5.1 优点&quot;">​</a></h2><ol><li><p><strong>读性能极致</strong>：无锁设计，读写并发无阻塞；</p></li><li><p><strong>安全易用</strong>：底层保证线程安全，API 与 ArrayList 一致；</p></li><li><p><strong>无并发修改异常</strong>：快照迭代避免 ConcurrentModificationException。</p></li></ol><h2 id="_5-2-缺点" tabindex="-1">5.2 缺点 <a class="header-anchor" href="#_5-2-缺点" aria-label="Permalink to &quot;5.2 缺点&quot;">​</a></h2><ol><li><p><strong>写成本高</strong>：全量复制数组，O(n) 时间+额外内存；</p></li><li><p><strong>弱一致性</strong>：读可能访问旧数据；</p></li><li><p><strong>内存压力大</strong>：写时双数组占用内存。</p></li></ol><h1 id="六、注意事项" tabindex="-1">六、注意事项 <a class="header-anchor" href="#六、注意事项" aria-label="Permalink to &quot;六、注意事项&quot;">​</a></h1><ul><li><p><strong>元素不可变优先</strong>：存储可变对象需额外同步内部状态，建议用 String、Integer 等；</p></li><li><p><strong>正视弱一致性</strong>：避免依赖迭代器实时性，需最新数据可重新获取迭代器；</p></li><li><p><strong>大数组慎用</strong>：元素过多时写复制成本激增，建议拆分容器；</p></li><li><p><strong>批量写优化</strong>：用 addAll() 替代多次 add()，减少复制次数。</p></li></ul><h1 id="七、核心知识点速记" tabindex="-1">七、核心知识点速记 <a class="header-anchor" href="#七、核心知识点速记" aria-label="Permalink to &quot;七、核心知识点速记&quot;">​</a></h1><pre><code>  1. 核心思想：写时复制，读无锁、写加锁；
  2. 底层结构：volatile 数组 + ReentrantLock；
  3. 迭代器特性：弱一致性，基于快照迭代；
  4. 性能特点：读快写慢，内存占用高；
  5. 适用场景：读多写少、弱一致性可接受。
</code></pre>`,34)])])}const u=t(e,[["render",l]]);export{g as __pageData,u as default};
